insert into public.experiences (role, organization, location, start_date, end_date, is_current, summary, highlights, sort_order) values ($q$Robotics R&D – UAV & Ground Robot Systems Integration | TÜBİTAK 1001$q$, $q$RAI Lab – Robotics & Artificial Intelligence Laboratory, Fırat University$q$, 'Elazığ, Türkiye', '07/2025', '08/2026', false, $q$TÜBİTAK 1001 project "Next Level Autonomy Development for Fast and Robust Disaster Management using Heterogeneous Robots Having Multi-sensors in Unstructured GPS-Denied Environments" (Grant No. 123E406) – responsible for the aerial-robotics (UAV) work package.$q$, ARRAY[$q$Designed and integrated the sensor payload of a DJI Matrice 350 RTK (Jetson Orin NX, Velodyne VLP-16 LiDAR, RealSense D435i) via DJI E-Port and Payload SDK; streamed the drone's built-in IMU into ROS 2, removing the need for an external IMU.$q$,$q$Deployed and tuned real-time LiDAR-inertial SLAM onboard the Jetson for GPS-denied mapping; evaluated SLAM methods (LIO-SAM, RKO-LIO) in Gazebo before field deployment.$q$,$q$Assembled, upgraded, maintained and field-tested ground robots (Unitree Go2, TurtleBot) and drones, including wiring, power regulation, sensor mounting and troubleshooting.$q$,$q$Designed and 3D-printed custom parts (sensor mounts, enclosures, brackets) and built functional prototypes for multiple lab projects.$q$,$q$Collected and organized a 20,000+ camera and LiDAR image dataset for disaster-scenario human detection; co-authored 3 peer-reviewed papers.$q$]::text[], 1);
insert into public.experiences (role, organization, location, start_date, end_date, is_current, summary, highlights, sort_order) values ($q$Robotics R&D Project Lead – Offline Multi-System AI Payload for Search & Rescue Robots | TÜBİTAK 2209-A$q$, $q$RAI Lab – Robotics & Artificial Intelligence Laboratory, Fırat University$q$, 'Elazığ, Türkiye', '02/2026', '09/2026', false, null, ARRAY[$q$Sole developer of an offline AI payload that turns any ROS 2 ground robot into a search-and-rescue robot: Jetson TX2 AI core + STM32 real-time sensor hub.$q$,$q$Integrated thermal (FLIR Lepton 3) + RGB cameras, a 24 GHz FMCW bio-radar, LiDAR and gas/flame/temperature sensors; deployed YOLOv11n victim detection with TensorRT and a thermal "Wake-on-Suspect" power mode.$q$,$q$Built a fully offline voice assistant (Faster-Whisper STT, Gemma 3 LLM via llama.cpp, Piper TTS) to guide trapped victims, with a SIGKILL-based state machine for safe AI-model switching on limited memory.$q$,$q$Developed hazard-aware navigation (Nav2, Cartographer) and dual Wi-Fi + LoRa telemetry with a command-center receiver; validated on TurtleBot3 and TurtleBot2. Research paper under review.$q$]::text[], 2);

